using System;
using System.Reflection;
using System.Linq;

class Program
{
    static void Main()
    {
        // Load the DLL
        var dll = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.agents.ai/1.13.0/lib/net9.0/Microsoft.Agents.AI.dll");

        Console.WriteLine("=== Microsoft.Agents.AI Namespaces ===");
        var namespaces = dll.GetTypes().Select(t => t.Namespace).Distinct().OrderBy(n => n).ToList();
        foreach (var ns in namespaces)
        {
            Console.WriteLine(ns);
        }

        Console.WriteLine("\n=== Key Public Types ===");
        var types = dll.GetTypes().Where(t => t.IsPublic).OrderBy(t => t.Namespace).ThenBy(t => t.Name).ToList();
        foreach (var type in types)
        {
            Console.WriteLine($"{type.Namespace}.{type.Name}");
        }

        // Focus on Agent-related types
        Console.WriteLine("\n=== Agent-related Types (detailed) ===");
        var agentTypes = types.Where(t => t.Name.Contains("Agent") || t.Name.Contains("Invoker")).ToList();
        foreach (var type in agentTypes)
        {
            Console.WriteLine($"\n--- {type.Namespace}.{type.Name} ---");
            Console.WriteLine($"Base: {type.BaseType?.Name}");

            var constructors = type.GetConstructors(BindingFlags.Public | BindingFlags.Instance);
            if (constructors.Length > 0)
            {
                Console.WriteLine("Constructors:");
                foreach (var ctor in constructors)
                {
                    var pars = string.Join(", ", ctor.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
                    Console.WriteLine($"  {type.Name}({pars})");
                }
            }

            var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly);
            if (methods.Length > 0)
            {
                Console.WriteLine("Methods:");
                foreach (var method in methods.Take(20))
                {
                    var pars = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name}"));
                    Console.WriteLine($"  {method.ReturnType.Name} {method.Name}({pars})");
                }
            }
        }
    }
}
