using System;
using System.Reflection;
using System.Linq;

class Program
{
    static void Main()
    {
        // Load the DLL
        var dll = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.agents.ai/1.13.0/lib/net9.0/Microsoft.Agents.AI.dll");

        // Focus on key agent classes
        Console.WriteLine("=== ChatClientAgent ===");
        var chatClientAgentType = dll.GetType("Microsoft.Agents.AI.ChatClientAgent");
        PrintTypeDetails(chatClientAgentType);

        Console.WriteLine("\n=== ChatClientAgentOptions ===");
        var optionsType = dll.GetType("Microsoft.Agents.AI.ChatClientAgentOptions");
        PrintTypeDetails(optionsType);

        Console.WriteLine("\n=== ChatClientAgentSession ===");
        var sessionType = dll.GetType("Microsoft.Agents.AI.ChatClientAgentSession");
        PrintTypeDetails(sessionType);

        Console.WriteLine("\n=== LoopAgent ===");
        var loopAgentType = dll.GetType("Microsoft.Agents.AI.LoopAgent");
        PrintTypeDetails(loopAgentType);

        Console.WriteLine("\n=== LoopContext ===");
        var loopContextType = dll.GetType("Microsoft.Agents.AI.LoopContext");
        PrintTypeDetails(loopContextType);

        Console.WriteLine("\n=== AgentSkill ===");
        var skillType = dll.GetType("Microsoft.Agents.AI.AgentSkill");
        PrintTypeDetails(skillType);

        Console.WriteLine("\n=== AgentSkillsProvider ===");
        var providerType = dll.GetType("Microsoft.Agents.AI.AgentSkillsProvider");
        PrintTypeDetails(providerType);

        // Now look at Microsoft.Extensions.AI
        Console.WriteLine("\n\n=== Microsoft.Extensions.AI.OpenAI Namespaces ===");
        try 
        {
            var extDll = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.extensions.ai.openai/9.0.0/lib/net9.0/Microsoft.Extensions.AI.OpenAI.dll");
            var extNamespaces = extDll.GetTypes().Select(t => t.Namespace).Distinct().OrderBy(n => n).ToList();
            foreach (var ns in extNamespaces)
            {
                if (!string.IsNullOrEmpty(ns))
                    Console.WriteLine(ns);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading OpenAI: {ex.Message}");
        }

        // Look for abstractions
        Console.WriteLine("\n=== Looking for AIFunction, ChatOptions, etc. ===");
        var allTypes = dll.GetTypes().Where(t => t.Name.Contains("Function") || t.Name.Contains("ChatOptions") || t.Name.Contains("Tool")).OrderBy(t => t.Name).ToList();
        foreach (var type in allTypes)
        {
            Console.WriteLine($"{type.Namespace}.{type.Name}");
        }
    }

    static void PrintTypeDetails(Type type)
    {
        if (type == null)
        {
            Console.WriteLine("Type not found");
            return;
        }

        Console.WriteLine($"Base: {type.BaseType?.Name ?? "none"}");
        Console.WriteLine($"Interfaces: {string.Join(", ", type.GetInterfaces().Select(i => i.Name))}");

        var constructors = type.GetConstructors(BindingFlags.Public | BindingFlags.Instance);
        if (constructors.Length > 0)
        {
            Console.WriteLine("Constructors:");
            foreach (var ctor in constructors)
            {
                var pars = string.Join(", ", ctor.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
                Console.WriteLine($"  {type.Name}({pars})");
            }
        }

        var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly).OrderBy(m => m.Name);
        if (methods.Any())
        {
            Console.WriteLine("Key Methods:");
            foreach (var method in methods.Where(m => !m.Name.StartsWith("get_") && !m.Name.StartsWith("set_")).Take(20))
            {
                var pars = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name}"));
                Console.WriteLine($"  {method.ReturnType.Name} {method.Name}({pars})");
            }
        }

        var props = type.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly);
        if (props.Length > 0)
        {
            Console.WriteLine("Properties:");
            foreach (var prop in props.Take(15))
            {
                var accessors = (prop.CanRead ? "get; " : "") + (prop.CanWrite ? "set; " : "");
                Console.WriteLine($"  {prop.PropertyType.Name} {prop.Name} {{ {accessors}}}");
            }
        }
    }
}
