static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "the history of the internet"
        : input;
}

// --- Tool definitions --------------------------------------------------------

/// <summary>Tools available to the research agent.</summary>
sealed class ResearchTools
{
    private readonly List<(string Category, string Content)> _notes = [];
    private readonly HttpClient _http = new();

    public int NoteCount => _notes.Count;

    [Description("Search the web for information on a query. Returns search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo instant-answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            _http.DefaultRequestHeaders.UserAgent.Clear();
            _http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

            var json = await _http.GetStringAsync(url, cancellationToken);

            using var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"\n");

            // Abstract / main answer
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                sb.AppendLine($"## Summary (from {abstractSource})");
                sb.AppendLine(abstractText);
                sb.AppendLine($"Source: {abstractUrl}\n");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var item in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var link = item.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        sb.AppendLine($"- {text}");
                        if (!string.IsNullOrWhiteSpace(link))
                            sb.AppendLine($"  Source: {link}");
                        count++;
                    }
                }
            }

            var result = sb.ToString();
            return string.IsNullOrWhiteSpace(result.Trim())
                ? $"No detailed results found for \"{query}\". Try a different query."
                : result;
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note under a specific category for later reference.")]
    public string SaveNote(
        [Description("The category or label for this note (e.g., 'Key Facts', 'History', 'Statistics')")] string category,
        [Description("The content of the note to save")] string content)
    {
        _notes.Add((category, content));
        Console.WriteLine($"  📝 Note saved [{category}]");
        return $"Note saved under \"{category}\". Total notes: {_notes.Count}.";
    }

    [Description("Retrieve all saved research notes, organized by category.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===\n");

        var grouped = _notes.GroupBy(n => n.Category);
        foreach (var group in grouped)
        {
            sb.AppendLine($"## {group.Key}");
            foreach (var (_, content) in group)
                sb.AppendLine($"- {content}");
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

